  /* --- story --- */
  'story.title': { th: 'บ้านหลังเล็ก', en: 'A little house' },
  'story.eyebrow': { th: 'Little House Flower · นนทบุรี', en: 'Little House Flower · Nonthaburi' },
  'story.p1': { th: 'Little House Flower เป็นร้านดอกไม้เล็กๆ ย่านรัตนาธิเบศร์ นนทบุรี จัดดอกไม้สดด้วยมือทีละช่อ และส่งไปทั่วนนทบุรีและกรุงเทพฯ ทุกวัน 08.00–20.00 น.', en: 'Little House Flower is a small florist in the Rattanathibet area of Nonthaburi. Every bouquet is hand-tied, one at a time, and sent across Nonthaburi and Bangkok, every day from 08.00 to 20.00.' },
  'story.p2': { th: 'ทุกช่อออกจากร้านพร้อมป้ายหัวใจสีชมพู และการ์ดข้อความที่ทางร้านเขียนด้วยลายมือให้ฟรี ริบบิ้น LOVE IS ETERNAL เป็นหนึ่งในแบบห่อที่ทางร้านใช้บ่อย ดอกไม้แต่ละชนิดมีความหมายต่างกัน ทางร้านจึงเขียนความหมายไว้ให้ เลือกจากสิ่งที่อยากบอกได้เลยค่ะ', en: 'Every bouquet leaves with our pink heart tag and a free handwritten card, and the LOVE IS ETERNAL ribbon is one of our signature wraps. Every flower means something, so we write the meanings down: choose by what you want to say.' },
  'story.how': { th: 'ขั้นตอนวิธีการสั่งดอกไม้', en: 'How to order' },   /* ›verbatim‹ FB post title */
  'story.how1': { th: 'รบกวนแจ้งวันเวลาที่ต้องการใช้', en: 'Tell us the date and time you need it' },
  'story.how2': { th: 'งบไม่เกินเท่าไหร่ดีคะ', en: 'Your budget ceiling' },
  'story.how3': { th: 'ดีเทลที่ต้องการให้แนะนำ เช่น สี รูปทรง ชนิดดอกไม้ ทางร้านจะรีบทำการเช็กสต็อกและส่งแบบให้ค่ะ', en: 'Details you’d like — colour, shape, flower type. We check stock and send you a design.' },
  'story.howShort': { th: 'วิธีสั่ง', en: 'Ordering' },
  'story.materialsEyebrow': { th: 'ทุกช่อ', en: 'With every bouquet' },
  'story.materials': { th: 'สิ่งที่มากับช่อของร้าน', en: 'What comes with a bouquet' },
