      if (st.reason === 'today') return t('ribbon.3');
      if (st.reason === 'cutoff') return t('cal.cutoff', { h: String(((opts.settings || {}).cutoffHour) || 18) + ':00' });
      if (st.reason === 'leadtime') return t('lead.days', { n: opts.leadDays || 1 });
